<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
adminRequireAuth();
$root=dirname(__DIR__);$file=$root.'/data/settings.json';$notice='';$error='';
$default=['site_name'=>'CHIMYON SCHOOL','site_title'=>'CHIMYON SCHOOL','site_description'=>'','logo'=>'','favicon'=>'','phone'=>'','email'=>'','address'=>'','telegram'=>'','instagram'=>'','working_hours'=>'','analytics'=>['enabled'=>false,'provider'=>'','id'=>'']];
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function readSettings(string $file,array $default):array{$raw=is_file($file)?file_get_contents($file):false;$data=is_string($raw)?json_decode($raw,true):null;if(!is_array($data))$data=$default;foreach($default as $k=>$v){if(!array_key_exists($k,$data))$data[$k]=$v;}if(!is_array($data['analytics']??null))$data['analytics']=$default['analytics'];foreach($default['analytics'] as $k=>$v)if(!array_key_exists($k,$data['analytics']))$data['analytics'][$k]=$v;return $data;}
function safeAsset(string $value,string $label):string{if($value!==''&&!preg_match('#^(?:https?://|/|\.\./|media/)#i',$value))throw new RuntimeException($label.' path xavfsiz formatda emas.');return $value;}
function saveJson(string $file,array $data):void{$json=json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false||file_put_contents($file,$json.PHP_EOL,LOCK_EX)===false)throw new RuntimeException('Settings JSON faylini saqlash amalga oshmadi.');}
$data=readSettings($file,$default);
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!adminVerifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('CSRF token noto‘g‘ri yoki sessiya eskirgan.');
 $action=(string)($_POST['action']??'settings');
 if($action==='rotate_key'){
   $current=(string)($_POST['current_key']??'');$new=(string)($_POST['new_key']??'');$confirm=(string)($_POST['new_key_confirm']??'');
   if(!adminVerifyKey($current))throw new RuntimeException('Joriy kalit noto‘g‘ri.');
   if(strlen($new)<10)throw new RuntimeException('Yangi kalit kamida 10 belgidan iborat bo‘lishi kerak.');
   if(strlen($new)>256)throw new RuntimeException('Yangi kalit 256 belgidan oshmasligi kerak.');
   if($new!==$confirm)throw new RuntimeException('Yangi kalitlar mos kelmadi.');
   $target=$root.'/config/admin_secret.php';$hash=password_hash($new,PASSWORD_DEFAULT);if($hash===false)throw new RuntimeException('Kalit hash qilinmadi.');
   $php="<?php\ndeclare(strict_types=1);\n\nreturn [\n    'admin_key_hash' => ".var_export($hash,true).",\n];\n";$configDir=dirname($target);if(!is_dir($configDir)&&!mkdir($configDir,0755,true))throw new RuntimeException('Config katalogi yaratilmadi.');
   if(file_put_contents($target,$php,LOCK_EX)===false)throw new RuntimeException('Admin key server konfiguratsiyasiga yozilmadi.');
   @chmod($target,0640);session_regenerate_id(true);$_SESSION['chimyon_admin_authenticated']=true;$_SESSION['chimyon_admin_login_at']=time();$_SESSION['chimyon_admin_csrf']=bin2hex(random_bytes(32));$notice='Admin access key muvaffaqiyatli almashtirildi.';
 }else{
   $data=['site_name'=>trim((string)($_POST['site_name']??'')),'site_title'=>trim((string)($_POST['site_title']??'')),'site_description'=>trim((string)($_POST['site_description']??'')),'logo'=>safeAsset(trim((string)($_POST['logo']??'')),'Logo'),'favicon'=>safeAsset(trim((string)($_POST['favicon']??'')),'Favicon'),'phone'=>trim((string)($_POST['phone']??'')),'email'=>trim((string)($_POST['email']??'')),'address'=>trim((string)($_POST['address']??'')),'telegram'=>trim((string)($_POST['telegram']??'')),'instagram'=>trim((string)($_POST['instagram']??'')),'working_hours'=>trim((string)($_POST['working_hours']??'')),'analytics'=>['enabled'=>isset($_POST['analytics_enabled']),'provider'=>trim((string)($_POST['analytics_provider']??'')),'id'=>trim((string)($_POST['analytics_id']??''))]];
   if($data['site_name']==='')throw new RuntimeException('Site name bo‘sh bo‘lishi mumkin emas.');if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email format noto‘g‘ri.');saveJson($file,$data);$notice='Global settings saqlandi.';
 }
}catch(Throwable $ex){$error=$ex->getMessage();}
